class SnapshotArray {
    private java.util.TreeMap<Integer, Integer>[] data;
    private int snapId;

    public SnapshotArray(int length) {
        data = new java.util.TreeMap[length];
        for (int i = 0; i < length; i++) {
            data[i] = new java.util.TreeMap<>();
            data[i].put(0, 0);
        }
        snapId = 0;
    }

    public void set(int index, int val) {
        data[index].put(snapId, val);
    }

    public int snap() {
        return snapId++;
    }

    public int get(int index, int snap_id) {
        return data[index].floorEntry(snap_id).getValue();
    }
}
